import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Grid,
  Stack,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import BuyerRequestInbox from '../compliance/BuyerRequestInbox';
import ApiService from '../../services/api';
import { reportingTabHref } from '../../constants/reportingTabs';

const BuyerAuditWarRoom: React.FC = () => {
  const [docCount, setDocCount] = useState(0);
  const [loading, setLoading] = useState(true);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const stats = await ApiService.request('/documents/statistics/overview');
      setDocCount(Number(stats?.data?.totalDocuments || 0));
    } catch {
      setDocCount(0);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  return (
    <Box>
      <Typography variant="h5" sx={{ fontWeight: 700, mb: 0.5 }}>
        Buyer audit pack
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3, maxWidth: '72ch' }}>
        Respond to buyer and bank audit requests from one place — track deadlines, gather evidence,
        and share reports.
      </Typography>

      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item xs={12} md={4}>
          <Card variant="outlined">
            <CardContent>
              <Typography variant="overline" color="text.secondary">
                Evidence on file
              </Typography>
              <Typography variant="h4" sx={{ fontWeight: 700 }}>
                {loading ? <CircularProgress size={24} /> : docCount}
              </Typography>
              <Typography variant="caption" color="text.secondary">
                documents uploaded
              </Typography>
              <Box sx={{ mt: 1.5 }}>
                <Button component={RouterLink} to="/document-upload" size="small" variant="contained">
                  Upload bills
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={8}>
          <Card variant="outlined">
            <CardContent>
              <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
                <Chip label="Buyer requests" color="primary" variant="outlined" />
                <Chip label="Audit-ready reports" variant="outlined" />
              </Stack>
              <BuyerRequestInbox />
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Alert severity="info" action={
        <Button component={RouterLink} to={reportingTabHref('overview')} color="inherit" size="small">
          Open reports
        </Button>
      }>
        Generate a shareable disclosure report once your assessment and documents are complete.
      </Alert>
    </Box>
  );
};

export default BuyerAuditWarRoom;
